/// </summary>
public readonly record struct Claim(Kind Kind, ResourceId Resource, Mode Mode, ScopeId Scope, Interval Size)
{
    /// <summary>§3.1.4a 归一化：resource 走 ResourceId.Normalize，size 缺省 ⇒ Default。</summary>
